namespace Analytics;

public static class WordTally
{
    /// <summary>
    /// Tally how often each word occurs, counting in parallel.
    /// </summary>
    public static Dictionary<string, int> Tally(IEnumerable<string> words)
    {
        var counts = new Dictionary<string, int>();
        Parallel.ForEach(words, word =>
        {
            // BUG: Dictionary is not thread-safe - concurrent writers corrupt
            // it (lost counts or InvalidOperationException).
            if (counts.ContainsKey(word))
                counts[word] = counts[word] + 1;
            else
                counts[word] = 1;
        });
        return counts;
    }
}

