using Analytics;

string[] vocab = { "alpha", "beta", "gamma", "delta" };
for (int round = 0; round < 5; round++)
{
    // 400k words, 4 hot keys - plain Dictionary loses counts or throws.
    var words = new List<string>(400_000);
    for (int i = 0; i < 400_000; i++) words.Add(vocab[i % 4]);

    Dictionary<string, int> counts;
    try
    {
        counts = WordTally.Tally(words);
    }
    catch (Exception e)
    {
        Console.Error.WriteLine($"round {round}: Tally threw {e.GetType().Name} - not thread-safe");
        Environment.Exit(1);
        return;
    }

    foreach (var v in vocab)
    {
        if (!counts.TryGetValue(v, out int n) || n != 100_000)
        {
            Console.Error.WriteLine($"round {round}: counts[{v}] = {(counts.ContainsKey(v) ? counts[v] : 0)}, want 100000 (lost updates)");
            Environment.Exit(1);
        }
    }
}

var single = WordTally.Tally(new[] { "x", "x", "y" });
if (single["x"] != 2 || single["y"] != 1) { Console.Error.WriteLine("small-input tally wrong"); Environment.Exit(1); }

Console.WriteLine("PASS");

